def icon(k):return '<svg viewBox="0 0 24 24" aria-hidden="true">'+icons.get(k,icons['heart'])+'</svg>'
def btn(label,url,style=''):return f'<a class="button {style}" href="{url}">{label}<span aria-hidden="true">↗</span></a>'
def link(label,url):return f'<a class="text-link" href="{url}">{label} <span aria-hidden="true">↗</span></a>'
def notice(msg):return f'<div class="notice">{icon("info")}<span>{msg}</span></div>'
def head(eyebrow,title,desc='',url='',label='Saiba mais'):return f'<div class="section-heading"><div><div class="eyebrow"><span class="dot"></span>{eyebrow}</div><h2>{title}</h2></div>'+ (f'<p>{desc}</p>' if desc else link(label,url) if url else '')+'</div>'
def section(content,cls=''):return f'<section class="section {cls}"><div class="wrap">{content}</div></section>'
brand='<span class="brand"><small>INSTITUTO</small><strong>mais amor</strong><em>Inclusão • Cuidado • Empatia</em><span class="brand-line"></span></span>'
logo=config.get('logo','')
if logo:
 candidate=(dist/logo).resolve()
 if not candidate.is_relative_to((dist/'assets').resolve()) or not candidate.is_file():
  raise ValueError('A logomarca precisa existir na pasta dist/assets antes de gerar o site.')
 brand='<span class="brand brand-official"><img src="'+E(logo,quote=True)+'" alt="Instituto Mais Amor — Acolhimento, Inclusão e Esperança para Todos" width="140" height="140"></span>'
navs=[('Início','index.html'),('O Instituto','instituto.html'),('Nossa Atuação','atuacao.html'),('Projetos','projetos.html'),('Seja um Parceiro','parcerias.html'),('Impacto','impacto.html'),('Contato','contato.html')]
def header(slug):return '<a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="utility"><div class="wrap"><span>Acolher, cuidar, incluir e transformar vidas.</span><div><a class="extra" href="finalidades.html">Compromisso institucional</a><a href="acessibilidade.html">Acessibilidade</a></div></div></div><div class="rainbow"></div><header class="'+('homepage-header' if slug=='index.html' else '')+'"><div class="wrap header-row"><a href="index.html" aria-label="Instituto Mais Amor — início">'+brand+'</a><nav id="navigation" aria-label="Menu principal">'+''.join(f'<a href="{u}"'+(' aria-current="page"' if u==({'atendimento.html':'atuacao.html','inclusao.html':'atuacao.html','finalidades.html':'instituto.html','voluntariado.html':'parcerias.html',**{'projeto-'+str(i)+'.html':'projetos.html' for i in range(1,9)}}.get(slug,slug)) else '')+'>'+n+'</a>' for n,u in navs)+'</nav>'+('<a class="button top-admin-login" href="/admin" target="_top"><svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/></svg>Painel administrativo</a>' if slug=='index.html' else '')+btn('Solicitar Acolhimento','acolhimento.html','small header-cta')+'<button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Abrir menu"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg></button></div></header>'
def footer():
 cols=[('Institucional',[('Quem Somos','instituto.html'),('Missão e Valores','instituto.html#missao'),('Finalidades Institucionais','finalidades.html')]),('Nossa Atuação',[('Cuidado Multidisciplinar','atendimento.html'),('Assistência Social','inclusao.html'),('Inclusão','inclusao.html'),('Projetos','projetos.html')]),('Participe',[('Voluntariado','voluntariado.html'),('Parcerias','parcerias.html'),('Contato','contato.html')]),('Informações',[('Política de Privacidade','privacidade.html'),('Canais Oficiais','contato.html'),('Acessibilidade','acessibilidade.html'),('Créditos de mídia','midia.html')])]
 return '<div class="rainbow"></div><footer class="footer"><div class="wrap"><div class="footer-grid"><div><a href="index.html" aria-label="Instituto Mais Amor — início">'+brand+'</a><p>Uma proposta institucional dedicada à dignidade humana, à inclusão, ao desenvolvimento e ao fortalecimento das famílias.</p></div>'+''.join('<div><h4>'+title+'</h4>'+''.join(f'<a href="{u}">{n}</a>' for n,u in links)+'</div>' for title,links in cols)+'</div><div class="footer-bottom"><span>© 2026 Instituto Mais Amor. Inclusão, Cuidado e Empatia.</span><span>Cada vida importa. Cada conquista merece ser possível.</span></div></div></footer><a class="back-top" href="#topo" aria-label="Voltar ao topo">↑</a>'
def page(slug,title,desc,body,eyebrow='Instituto Mais Amor',home=False):
 intro='' if home else f'<div class="page-intro"><div class="wrap"><div class="breadcrumb"><a href="index.html">Início</a> <span aria-hidden="true"> / </span> {E(title)}</div><div class="eyebrow"><span class="dot"></span>{eyebrow}</div><h1>{title}</h1><p>{desc}</p></div></div>'
 doc=f'<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Instituto Mais Amor</title><meta name="description" content="{E(desc)}"><meta property="og:title" content="{E(title)} | Instituto Mais Amor"><meta property="og:description" content="{E(desc)}"><meta property="og:type" content="website"><meta name="theme-color" content="#064BFF"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="modern.css"><link rel="icon" href="assets/logo-instituto-mais-amor.jpeg" type="image/jpeg"></head><body id="topo">'+header(slug)+'<main id="conteudo" tabindex="-1">'+intro+body+'</main>'+footer()+'<script type="module" src="app.js"></script><script type="module" src="public-center.js"></script></body></html>'
 if home:
  doc=doc.replace('</head>','<link rel="stylesheet" href="media-admin.css"><link rel="stylesheet" href="video-card.css"></head>')
  doc=doc.replace('</body>','<script type="module" src="hero-video.js"></script></body>')
 (dist/slug).write_text(doc)
colors=['#1768b2','#1c72bc','#a56b00','#b52d3b','#245c9a']
