def projectcards(limit=8):
 images=['familia-inclusiva.jpg','educacao-diversa.jpg','aprender-juntos.jpg','educacao-diversa.jpg','aprender-juntos.jpg','familia-inclusiva.jpg','educacao-diversa.jpg','aprender-juntos.jpg']
 return '<div class="grid">'+''.join(f'<article class="card project-card" data-status="{status_keys[p['status']]}"><div class="project-art project-photo"><img src="assets/{images[i]}" alt="" width="1200" height="800" loading="lazy"><span class="project-index">{p["id"].zfill(2)}</span></div><div class="project-body"><span class="status" data-state="{status_keys[p['status']]}">{p["status"]}</span><h3>{p["title"]}</h3><p>{p["text"]}</p>{link("Conheça a proposta","projeto-"+p["id"]+".html")}</div></article>' for i,p in enumerate(projects[:limit]))+'</div>'
