commit=section('<div class="commitment"><div><div class="eyebrow">Gratuidade e compromisso social</div><h2>O cuidado e a dignidade não devem ser privilégios.</h2><p>O Instituto Mais Amor estabelece, entre suas finalidades estatutárias, o compromisso com atividades, atendimentos e terapias gratuitos, contínuos e sem discriminação.</p>'+link('Leia nossas finalidades institucionais','finalidades.html')+'</div><div class="pillars">'+''.join(f'<div class="pillar">{icon(k)}<h3>{t}</h3><p>{d}</p></div>' for k,t,d in [('heart','Gratuidade','Compromisso institucional com a oferta gratuita das atividades e serviços.'),('people','Igualdade','Respeito sem distinção de nacionalidade, raça, cor, sexo, crença ou orientação política.'),('shield','Dignidade','Valorização da pessoa humana, de suas capacidades, necessidades e direitos.')])+'</div></div>','navy')
