 body=section('<div class="split"><div><span class="status">'+p['status']+'</span><h2>Uma proposta para construir possibilidades.</h2><p>'+p['text']+'</p>'+('<p>'+p['tail']+'</p>' if p['tail'] else '')+'<h3>Objetivos e possibilidades</h3><ul class="list">'+''.join('<li>'+E(g)+'</li>' for g in p['goals'])+'</ul>'+notice('Situação informada: '+p['status']+'. Consulte os canais oficiais para confirmar atividades, vagas e critérios de participação.')+'</div><div class="visual-block"><div class="eyebrow">Projeto '+p['id'].zfill(2)+'</div><div class="big-word">'+p['title']+'</div></div></div><div class="actions">'+btn('Conheça o acolhimento','acolhimento.html')+btn('Explore outros projetos','projetos.html','light')+'</div>')
