def form(kind):
 kind='parcerias' if kind=='parceria' else kind
 return '<div class="split"><div><div class="eyebrow">Manifestação de interesse</div><h2>Vamos construir essa rede juntos.</h2><p>Deixe seu contato para a equipe do Instituto conhecer seu interesse e organizar o retorno.</p>'+notice('Não inclua laudos, documentos ou informações de saúde. O envio não garante vaga, atendimento ou parceria.')+link('Como usamos seus dados','privacidade.html')+'</div><form data-interest="'+kind+'"><fieldset><legend>Seu primeiro contato</legend><label for="nome">Nome</label><input id="nome" name="nome" autocomplete="name" minlength="2" maxlength="100" required><label for="retorno">Telefone com DDD ou e-mail</label><input id="retorno" name="contato" maxlength="150" required><label for="organizacao">Organização ou área de interesse opcional</label><input id="organizacao" name="organizacao" maxlength="150"><label for="mensagem">Mensagem opcional</label><textarea id="mensagem" name="mensagem" maxlength="600" placeholder="Compartilhe somente o necessário para o primeiro contato."></textarea><div hidden aria-hidden="true"><label>Site<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="check"><input name="ciente" type="checkbox" required><span>Autorizo o uso destes dados para receber retorno sobre esta solicitação. Li a <a href="privacidade.html">Política de Privacidade</a>.</span></label><button class="button" type="submit">Enviar interesse</button></fieldset><p role="status" class="form-result" tabindex="-1"></p><small>A confirmação do envio significa apenas que a solicitação foi registrada.</small></form></div>'
page('parcerias.html','Grandes transformações nascem de compromissos compartilhados.','O Instituto Mais Amor possui entre suas finalidades a articulação com órgãos públicos e entidades privadas para fortalecer a defesa de direitos, promover inclusão e construir novas oportunidades.',section('<div class="grid two">'+''.join('<article class="card"><div class="icon">'+icon('people')+'</div><h3>'+t+'</h3><p>'+d+'</p></article>' for t,d in partnercats)+'</div>'+notice('Não há parcerias formalizadas confirmadas para divulgação nesta versão.'))+section('<div id="interesse">'+form('parceria')+'</div>','soft'))
page('voluntariado.html','Seu conhecimento, seu tempo e sua presença podem transformar realidades.','Conheça possibilidades futuras de voluntariado e participação na construção de uma rede de inclusão.',section('<div class="article"><h2>Muitas formas de contribuir.</h2><p>As possibilidades de participação serão definidas conforme a estrutura, os projetos e os critérios institucionais. O interesse em colaborar não equivale a uma inscrição aprovada.</p><div class="values">'+''.join('<span class="pill">'+v+'</span>' for v in ['Ações sociais','Eventos comunitários','Educação','Tecnologia','Comunicação','Cultura','Inclusão','Apoio administrativo','Projetos sociais'])+'</div></div>')+section(form('voluntariado'),'soft'))
(dist/'transparencia.html').write_text('<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><title>Documentos internos</title></head><body><main><h1>Documentos internos</h1><p>A consulta está na área administrativa.</p><a href="/admin#documentos-internos">Acessar administração</a></main></body></html>')
page('contato.html','Uma conversa pode abrir novos caminhos.','Consulte os canais oficiais do Instituto Mais Amor e conheça as possibilidades de aproximação.',section('<div id="official-contacts" class="article"><h2>Canais oficiais</h2><div class="empty">Os contatos institucionais ainda não foram fornecidos para este portal. E-mail, WhatsApp, Instagram, endereço e horário serão exibidos somente após confirmação.</div>'+notice('Você pode registrar sua mensagem no formulário abaixo e guardar o protocolo de envio.')+'<div class="actions">'+btn('Conheça o acolhimento','acolhimento.html')+btn('Seja um parceiro','parcerias.html','light')+'</div></div>')+section(head('Antes de entrar em contato','Informação com responsabilidade.')+faqs,'soft'))
privacy=[('Quem utiliza os dados','O Instituto Mais Amor utiliza os dados enviados para organizar manifestações de interesse e responder a contatos. O acesso aos registros é restrito à administração do projeto.'),('O que coletamos e para quê','Nome, telefone ou e-mail, organização ou área de interesse opcional e mensagem opcional. Usamos essas informações para analisar e retornar sua solicitação de parceria, voluntariado, acolhimento ou contato. A autorização específica é solicitada antes do envio, sem adesão automática a publicidade.'),('Armazenamento e acesso','Os registros são guardados no banco de dados da hospedagem Sites e acessados por painel administrativo com autenticação. A hospedagem pode tratar informações técnicas conforme suas condições. Não vendemos os dados nem exibimos cadastros publicamente.'),('Cuidados ao preencher','Este canal é para primeiro contato de pessoas adultas. Não envie documentos, diagnósticos, laudos, dados de crianças ou informações de saúde. Não é um serviço de urgência e não garante vagas ou atendimento.'),('Prazos e direitos','A administração deve revisar os registros periodicamente e excluir dados quando deixarem de ser necessários. Você pode pedir acesso, correção, revogação da autorização ou exclusão pelo próprio formulário de contato, identificando a solicitação pelo protocolo. A equipe verificará sua identidade proporcionalmente antes de responder.'),('Fornecedores e atualização','A infraestrutura de hospedagem e banco de dados é fornecida pela plataforma Sites. Informações institucionais e canais externos serão complementados após confirmação pela direção. Esta política deve acompanhar alterações no tratamento de dados.')]
page('privacidade.html','Política de Privacidade','Uso de dados para primeiro contato e manifestações de interesse. Atualizada em 8 de novembro de 2026.',section('<div class="article">'+''.join('<h2 style="font-size:24px;margin-top:35px">'+t+'</h2><p>'+d+'</p>' for t,d in privacy)+'</div>'))
page('acessibilidade.html','A inclusão também começa na experiência digital.','Recursos e práticas para facilitar a navegação pelo portal.',section('<div class="article"><h2>Navegue do seu jeito.</h2><p>O portal oferece navegação por teclado, link para pular ao conteúdo, indicadores de foco, títulos organizados, textos alternativos, formulários identificados e adaptação a celulares e ampliação de texto.</p><p>Use Tab para percorrer os controles, Enter para abrir links e Enter ou Espaço para expandir perguntas. O menu móvel também pode ser fechado com Escape. A preferência do sistema por movimento reduzido é respeitada.</p><p>Buscamos boas práticas WCAG 2.2 nível AA. Esta página não representa certificação de conformidade. Novas avaliações e melhorias deverão acompanhar a evolução do portal.</p>'+link('Consultar canais de contato','contato.html')+'</div>'))
page('midia.html','Imagens que representam possibilidades.','Créditos, descrição acessível e contexto das imagens ilustrativas deste portal.',section('<div class="article"><h2>Representatividade com transparência.</h2><p>As fotografias e os vídeos são ilustrativos e não representam beneficiários, profissionais ou atendimentos do Instituto Mais Amor. A presença de pessoas negras e de crianças com síndrome de Down integra a direção de comunicação solicitada. Não se infere qualquer diagnóstico pela aparência.</p><h2 style="font-size:26px">Descrição do vídeo de chamada</h2><p>Uma montagem de oito segundos apresenta duas cenas lado a lado: à esquerda, uma menina ao ar livre, com cabelos se movimentando ao vento; à direita, um menino negro brinca de fazer bolhas de sabão. O vídeo não contém fala nem trilha sonora. A reprodução começa apenas mediante ação da pessoa visitante e pode ser pausada pelos controles do player.</p><h2 style="font-size:26px">Vídeos e fotografias</h2><ul class="list"><li>RDNE Stock project — <a href="https://www.pexels.com/video/a-girl-out-on-a-windy-day-7402746/">A Girl Out On A Windy Day</a>. A descrição do fornecedor identifica a menina como uma pessoa com síndrome de Down.</li><li>Pavel Danilyuk — <a href="https://www.pexels.com/video/a-little-boy-blowing-bubbles-8160571/">A Little Boy Blowing Bubbles</a>. Menino negro brincando com bolhas de sabão.</li><li>Nicola Barts — <a href="https://www.pexels.com/photo/a-woman-and-a-young-girl-using-laptop-together-7943976/">Mãe e filha utilizando um computador</a> e <a href="https://www.pexels.com/photo/a-young-girl-playing-on-the-table-7943259/">Menina em uma atividade de aprendizagem</a>. As descrições do fornecedor identificam a criança como uma pessoa com síndrome de Down.</li><li>Katerina Holmes — <a href="https://www.pexels.com/photo/black-teacher-with-smart-kids-in-classroom-5905935/">Professor e crianças em sala de aula</a>.</li></ul><p>Materiais disponibilizados sob a <a class="text-link" href="https://www.pexels.com/license/">licença Pexels</a>. A utilização não indica endosso das pessoas retratadas ao Instituto. O vídeo reúne cenas independentes; não sugere que as pessoas se encontraram.</p><h2 style="font-size:26px">Identidade visual</h2><p>A marca institucional fornecida foi aplicada preservando a imagem original e o fundo branco. Os elementos de quebra-cabeça são detalhes gráficos decorativos escolhidos para este projeto. A imagem do encontro no parque foi criada com inteligência artificial como ilustração de inclusão; não é registro documental nem comprovação de uma atividade do Instituto.</p></div>'))
for slug,kind in [('acolhimento.html','acolhimento'),('contato.html','contato')]:
 p=dist/slug; text=p.read_text(); text=text.replace('</main>',section(('<div id="solicitar-acolhimento">'+form(kind)+'</div>') if kind=='acolhimento' else form(kind),'soft')+'</main>');p.write_text(text)
origin=config.get('siteUrl','').rstrip('/')
if origin and not origin.startswith('https://'):
 raise ValueError('Use uma URL HTTPS em siteUrl, ou deixe em branco até confirmar o domínio.')
(dist/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /admin\nDisallow: /api/admin/\nDisallow: /api/anexos/\nDisallow: /documentos/\nDisallow: /transparencia\n'+('Sitemap: '+origin+'/sitemap.xml\n' if origin else ''))
if origin:
 (dist/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+html.escape(origin+'/'+p.name)+'</loc></url>' for p in sorted(dist.glob('*.html')) if p.name not in ['admin.html','transparencia.html'])+'</urlset>')
else:
 (dist/'sitemap.xml').unlink(missing_ok=True)
